package com.sabyeguyz.clinic.staff;
import com.sabyeguyz.clinic.auth.AppUser; import com.sabyeguyz.clinic.auth.AppUserRepository; import com.sabyeguyz.clinic.auth.Role; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@org.springframework.context.annotation.Profile("!database-v2")
@RestController @RequestMapping("/api/staff") public class StaffController { private final StaffRepository staffRepository; private final AppUserRepository userRepository; public StaffController(StaffRepository s,AppUserRepository u){staffRepository=s;userRepository=u;} public record Request(@NotNull Long userId,@NotBlank @Size(max=40) String employeeCode,@NotBlank @Size(max=160) String fullName,String phone){} public record Response(Long id,Long userId,String username,Role role,String employeeCode,String fullName,String phone,boolean active){} @GetMapping List<Response> list(){return staffRepository.findAllByOrderByFullName().stream().map(StaffController::response).toList();} @GetMapping("/{id}") Response get(@PathVariable Long id){return response(find(id));} @PostMapping @ResponseStatus(HttpStatus.CREATED) Response create(@Valid @RequestBody Request r){if(staffRepository.findByEmployeeCode(r.employeeCode().trim()).isPresent())throw new IllegalArgumentException("รหัสพนักงานซ้ำ"); AppUser u=userRepository.findById(r.userId()).orElseThrow(()->new IllegalArgumentException("ไม่พบ UserAccount")); if(staffRepository.existsById(u.getId()))throw new IllegalArgumentException("UserAccount นี้มี Staff แล้ว"); return response(staffRepository.save(new Staff(u,r.employeeCode().trim(),r.fullName().trim(),r.phone())));} @PutMapping("/{id}") Response update(@PathVariable Long id,@Valid @RequestBody Request r){Staff s=find(id);String code=r.employeeCode().trim();if(staffRepository.findByEmployeeCode(code).filter(f->!f.getId().equals(id)).isPresent())throw new IllegalArgumentException("รหัสพนักงานซ้ำ");if(!s.getUser().getId().equals(r.userId()))throw new IllegalArgumentException("ไม่อนุญาตให้เปลี่ยน UserAccount ของ Staff");s.update(code,r.fullName().trim(),r.phone());return response(staffRepository.save(s));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void deactivate(@PathVariable Long id){Staff s=find(id);s.deactivate();staffRepository.save(s);} private Staff find(Long id){return staffRepository.findById(id).orElseThrow(StaffNotFoundException::new);} private static Response response(Staff s){return new Response(s.getId(),s.getUser().getId(),s.getUser().getUsername(),s.getUser().getRole(),s.getEmployeeCode(),s.getFullName(),s.getPhone(),s.isActive());} }
